    stem: "Mauna Kea is deemed as an ideal astronomical site due to",
    options: [{ key: "A", text: "its geographical features." }, { key: "B", text: "its protective surroundings." }, { key: "C", text: "its religious implications." }, { key: "D", text: "its existing infrastructure." }],
